import numpy as np
from collections import defaultdict
from typing import List, Dict, Any, Tuple
import math # For math.log2

class Project:
    def __init__(self, project_id: str, base_reward: float, resource_needed: int, current_resources: int = 0):
        self.project_id = project_id
        self.base_reward = base_reward
        self.resource_needed = resource_needed
        self.current_resources = current_resources
        self.completed = False
        self.round_completed = -1 

    def add_resources(self, amount: int):
        self.current_resources += amount
        if self.current_resources >= self.resource_needed and not self.completed:
            self.completed = True

    def get_reward(self) -> float:
        if self.completed:
            return self.base_reward
        return 0

    def reset_for_new_round(self):
        self.current_resources = 0 
        self.completed = False
        self.round_completed = -1

    def change_parameters(self, new_reward: float = None, new_resource_needed: int = None):
        if new_reward is not None:
            self.base_reward = new_reward
        if new_resource_needed is not None:
            self.resource_needed = new_resource_needed


class ResourceAllocatingAgent:
    def __init__(self, agent_id: str, all_agent_ids: List[str], num_agents: int, learning_rate: float = 0.1, epsilon_start: float = 0.2, epsilon_end: float = 0.05, mutation_rate: float = 0.05, is_fixed_strategy: bool = False, fixed_project_id: str = None, specialization_incentive_rate: float = 0.05, preferred_project: str = None):
        self.agent_id = agent_id
        self.all_agent_ids = all_agent_ids
        self.num_agents = num_agents
        self.total_reward = 0
        self.current_round_reward_contribution = 0 
        self.learning_rate = learning_rate
        self.epsilon_start = epsilon_start
        self.epsilon_end = epsilon_end
        self.mutation_rate = mutation_rate
        self.is_fixed_strategy = is_fixed_strategy
        self.fixed_project_id = fixed_project_id 
        self.specialization_incentive_rate = specialization_incentive_rate
        self.preferred_project = preferred_project

        self.allocation_strategy = defaultdict(lambda: {'success': 1, 'attempts': 2, 'value_est': 0.5}) 
        if self.preferred_project:
            self.allocation_strategy[self.preferred_project]['value_est'] = 0.7 # Initial bias for preferred project

        self.reputations = {aid: 0.5 for aid in all_agent_ids if aid != agent_id}

        self.allocation_history_window = 20 # Increased window
        self.recent_allocations = defaultdict(lambda: []) 
        self.specialization_index = 0.0 
        self.most_allocated_project = "None"
        self.specialization_nudge_rounds = 0 # Counter for temporary nudge

        print(f"Resource Allocating Agent {self.agent_id} initialized (Fixed Strategy: {self.is_fixed_strategy}, Learning Rate: {self.learning_rate:.2f}, Mutation Rate: {self.mutation_rate:.2f}, Preferred: {self.preferred_project}).")

    def _get_epsilon(self, current_round: int, total_rounds: int) -> float:
        if self.is_fixed_strategy: return 0.0 
        decay_rate = (self.epsilon_start - self.epsilon_end) / total_rounds
        return max(self.epsilon_end, self.epsilon_start - decay_rate * current_round)

    def choose_allocation(self, my_available_resource: int, projects: Dict[str, Project], current_round: int, total_rounds: int) -> Dict[str, int]:
        allocations = defaultdict(int)

        if self.is_fixed_strategy:
            current_project_ids = list(projects.keys())
            if not current_project_ids: 
                return allocations

            if self.fixed_project_id in projects and not projects[self.fixed_project_id].completed:
                allocations[self.fixed_project_id] += my_available_resource
            else: 
                available_projects = [p for p in projects.values() if not p.completed]
                if available_projects:
                    best_available_project = max(available_projects, key=lambda p: p.base_reward) 
                    allocations[best_available_project.project_id] += my_available_resource
                else: 
                    chosen_project = np.random.choice(current_project_ids)
                    allocations[chosen_project] += my_available_resource
            return allocations

        current_epsilon = self._get_epsilon(current_round, total_rounds)

        if np.random.rand() < current_epsilon:
            for _ in range(my_available_resource):
                chosen_project = np.random.choice(list(projects.keys())) if projects else None
                if chosen_project:
                    allocations[chosen_project] += 1
        else:
            project_utilities = {}
            for project_id, project in projects.items():
                if not project.completed:
                    project_utilities[project_id] = self.allocation_strategy[project_id]['value_est'] 
                    if project.resource_needed > 0: 
                        project_utilities[project_id] += (project.base_reward / project.resource_needed) * 0.1 
                else: 
                    project_utilities[project_id] = -float('inf') 

            if not project_utilities or all(util == -float('inf') for util in project_utilities.values()):
                chosen_project = np.random.choice(list(projects.keys())) if projects else None
                if chosen_project:
                    allocations[chosen_project] += my_available_resource
            else:
                # Specialization Nudge: If agent needs nudging, strongly prioritize its most allocated project
                if self.specialization_nudge_rounds > 0 and self.most_allocated_project != "None" and self.most_allocated_project in project_utilities:
                    # Temporarily boost utility of the most allocated project
                    project_utilities[self.most_allocated_project] += 1.0 # Strong boost
                    self.specialization_nudge_rounds -= 1
                    # print(f"  Agent {self.agent_id} NUDGED towards {self.most_allocated_project}. Nudges left: {self.specialization_nudge_rounds}")

                sorted_projects = sorted(project_utilities.items(), key=lambda item: item[1], reverse=True)

                resources_left = my_available_resource
                for project_id, utility in sorted_projects:
                    if resources_left == 0: break
                    if utility == -float('inf'): continue 

                    allocations[project_id] += resources_left 
                    resources_left = 0 

        return allocations

    def update_learning(self, my_allocations: Dict[str, int], collective_round_reward: float, completed_projects_this_round: List[str], projects_map: Dict[str, Project], max_possible_collective_reward_this_round: float):
        self.total_reward += collective_round_reward 

        if self.is_fixed_strategy: return 

        self.current_round_reward_contribution = 0

        for project_id, allocated_amount in my_allocations.items():
            if allocated_amount > 0 and project_id in completed_projects_this_round:
                self.current_round_reward_contribution += 1.0 

        is_successful_round_for_me = self.current_round_reward_contribution > 0

        for project_id in projects_map.keys():
            if project_id not in self.allocation_strategy:
                self.allocation_strategy[project_id] = {'success': 1, 'attempts': 2, 'value_est': 0.5}

            self.allocation_strategy[project_id]['attempts'] += 1

            reward_signal = 0.0 
            if project_id in completed_projects_this_round and my_allocations.get(project_id, 0) > 0:
                reward_signal = projects_map[project_id].base_reward / max_possible_collective_reward_this_round 
            elif not is_successful_round_for_me: 
                reward_signal = -0.05 

            self.allocation_strategy[project_id]['value_est'] = \
                (1 - self.learning_rate) * self.allocation_strategy[project_id]['value_est'] + \
                self.learning_rate * reward_signal

        if self.specialization_index > 0.8: # Stronger condition for incentive
            self.total_reward += self.specialization_incentive_rate * collective_round_reward # Significant bonus

    def update_reputation_from_round_outcome(self, collective_round_reward: float, max_possible_collective_reward_this_round: float):
        if self.is_fixed_strategy: return 

        scaled_reward_factor = (collective_round_reward / max_possible_collective_reward_this_round) * 2 - 1 if max_possible_collective_reward_this_round > 0 else 0 
        for aid in self.reputations.keys():
            self.reputations[aid] = np.clip(self.reputations[aid] + self.learning_rate * scaled_reward_factor * 0.1, 0, 1)

    def record_allocations(self, current_allocations: Dict[str, int]):
        for pid, amount in current_allocations.items():
            self.recent_allocations[pid].append(amount)
            if len(self.recent_allocations[pid]) > self.allocation_history_window:
                self.recent_allocations[pid].pop(0)

    def calculate_specialization_index(self, num_current_projects: int) -> Tuple[str, float]:
        total_allocated_in_window = sum(sum(amounts) for amounts in self.recent_allocations.values())
        if total_allocated_in_window == 0:
            self.specialization_index = 0.0
            self.most_allocated_project = "None"
            return "None", 0.0

        project_sums = {pid: sum(amounts) for pid, amounts in self.recent_allocations.items()}

        positive_proportions = np.array([count / total_allocated_in_window for count in project_sums.values() if count > 0])

        if len(positive_proportions) > 1:
            entropy = -np.sum(positive_proportions * np.log2(positive_proportions))
            # Max entropy if perfectly even distribution among *currently active projects*
            max_entropy = math.log2(len(positive_proportions)) if len(positive_proportions) > 0 else 0.0 
            specialization_index = 1 - (entropy / max_entropy) if max_entropy > 0 else 0.0
        else: 
            specialization_index = 1.0 if len(positive_proportions) == 1 else 0.0

        most_allocated_project = max(project_sums, key=project_sums.get) if project_sums else "None"

        self.specialization_index = specialization_index
        self.most_allocated_project = most_allocated_project
        return most_allocated_project, specialization_index

    def consider_strategy_adoption(self, all_agents: Dict[str, 'ResourceAllocatingAgent'], current_round: int, total_rounds: int,
                                   adoption_threshold_self_reward_factor: float = 0.5, 
                                   adoption_threshold_other_rep: float = 0.8, 
                                   top_n_percent_mentors: float = 0.25, max_possible_collective_reward_per_round: float = 0,
                                   specialization_nudge_threshold: float = 0.4): # If specialization is below this, consider nudging
        if self.is_fixed_strategy: return 

        expected_total_reward_for_current_round = max_possible_collective_reward_per_round * (current_round + 1)

        dynamic_self_reward_threshold = expected_total_reward_for_current_round * adoption_threshold_self_reward_factor

        if self.total_reward < dynamic_self_reward_threshold: 
            sorted_agents = sorted([a for a in all_agents.values() if not a.is_fixed_strategy], key=lambda a: a.total_reward, reverse=True)
            num_top_mentors = max(1, int(len([a for a in all_agents.values() if not a.is_fixed_strategy]) * top_n_percent_mentors))

            potential_mentors = []
            for mentor_candidate in sorted_agents[:num_top_mentors]: 
                if mentor_candidate.agent_id == self.agent_id: continue

                if self.reputations.get(mentor_candidate.agent_id, 0.0) >= adoption_threshold_other_rep:
                    potential_mentors.append(mentor_candidate)

            if potential_mentors:
                mentor = max(potential_mentors, key=lambda a: a.total_reward)
                # print(f"  Agent {self.agent_id} (Total Reward {self.total_reward:.2f}) adopting strategy from {mentor.agent_id} (Total Reward {mentor.total_reward:.2f}).")

                for pid in mentor.allocation_strategy.keys():
                    self.allocation_strategy[pid] = mentor.allocation_strategy[pid].copy()

                if np.random.rand() < self.mutation_rate:
                    # print(f"    Agent {self.agent_id} mutates adopted strategy.")
                    for pid in self.allocation_strategy.keys():
                        self.allocation_strategy[pid]['value_est'] = np.clip(self.allocation_strategy[pid]['value_est'] + np.random.uniform(-0.1, 0.1), 0, 1)

                self.epsilon_start = 0.2 # Reset epsilon for new exploration after adoption/mutation

        # Check for specialization nudge (if not adopting and not already specialized)
        if self.specialization_index < specialization_nudge_threshold and self.specialization_nudge_rounds == 0 and current_round > 100: # Only nudge after some initial learning
            if np.random.rand() < 0.2: # 20% chance to initiate a nudge sequence
                self.specialization_nudge_rounds = 5 # Nudge for 5 rounds
                print(f"  Agent {self.agent_id} initiated a specialization nudge sequence.")

class ResourceAllocationEnvironment:
    def __init__(self, num_agents: int, total_resource_per_round: int = 10):
        self.num_agents = num_agents
        self.total_resource_per_round = total_resource_per_round
        self.projects: Dict[str, Project] = {}

        self.projects['Project_A'] = Project('Project_A', base_reward=10, resource_needed=5) 
        self.projects['Project_B'] = Project('Project_B', base_reward=15, resource_needed=7) 
        self.projects['Project_C'] = Project('Project_C', base_reward=8, resource_needed=4) 

        self.max_possible_collective_reward_per_round = sum(p.base_reward for p in self.projects.values()) 

        print(f"Environment initialized for {num_agents} agents, {len(self.projects)} projects, {total_resource_per_round} resources/round.")

    def add_project(self, project_id: str, base_reward: float, resource_needed: int):
        if project_id not in self.projects:
            self.projects[project_id] = Project(project_id, base_reward, resource_needed)
            self.max_possible_collective_reward_per_round = sum(p.base_reward for p in self.projects.values())
            return True
        return False

    def remove_project(self, project_id: str):
        if project_id in self.projects:
            del self.projects[project_id]
            self.max_possible_collective_reward_per_round = sum(p.base_reward for p in self.projects.values())
            return True
        return False

    def update_project_params(self, project_id: str, new_reward: float = None, new_resource_needed: int = None):
        if project_id in self.projects:
            self.projects[project_id].change_parameters(new_reward, new_resource_needed)
            self.max_possible_collective_reward_per_round = sum(p.base_reward for p in self.projects.values())
            return True
        return False

    def distribute_and_resolve(self, collective_allocations: Dict[str, int]) -> Tuple[Dict[str, float], float, List[str]]:
        for project in self.projects.values():
            project.current_resources = 0 
            project.completed = False

        for project_id, amount in collective_allocations.items():
            if project_id in self.projects:
                self.projects[project_id].add_resources(amount)

        current_project_rewards = {}
        completed_projects_this_round = []
        for project_id, project in self.projects.items():
            current_project_rewards[project_id] = project.get_reward()
            if project.completed:
                completed_projects_this_round.append(project_id)

        total_collective_reward = sum(current_project_rewards.values())

        return current_project_rewards, total_collective_reward, completed_projects_this_round

# --- Simulation Setup ---
NUM_AGENTS = 5
NUM_ROUNDS = 600 
TOTAL_RESOURCE_PER_ROUND = 15 

all_agent_ids = [f"Agent_{i+1}" for i in range(NUM_AGENTS)]

agents_dict = {}

# Assign initial preferred projects for learning agents
project_pool = ['Project_A', 'Project_B', 'Project_C'] # Initial projects

agents_dict['Agent_1'] = ResourceAllocatingAgent('Agent_1', all_agent_ids, NUM_AGENTS, learning_rate=0.2, epsilon_start=0.2, epsilon_end=0.05, mutation_rate=0.05, specialization_incentive_rate=0.05, preferred_project=project_pool[0])
agents_dict['Agent_2'] = ResourceAllocatingAgent('Agent_2', all_agent_ids, NUM_AGENTS, learning_rate=0.2, epsilon_start=0.2, epsilon_end=0.05, mutation_rate=0.05, specialization_incentive_rate=0.05, preferred_project=project_pool[1])
agents_dict['Agent_3'] = ResourceAllocatingAgent('Agent_3', all_agent_ids, NUM_AGENTS, learning_rate=0.1, epsilon_start=0.3, epsilon_end=0.1, mutation_rate=0.05, specialization_incentive_rate=0.03, preferred_project=project_pool[2]) 
agents_dict['Agent_4'] = ResourceAllocatingAgent('Agent_4', all_agent_ids, NUM_AGENTS, learning_rate=0.2, epsilon_start=0.2, epsilon_end=0.05, mutation_rate=0.15, specialization_incentive_rate=0.07, preferred_project=project_pool[0]) 
agents_dict['Agent_5'] = ResourceAllocatingAgent('Agent_5', all_agent_ids, NUM_AGENTS, is_fixed_strategy=True, fixed_project_id='Project_B', learning_rate=0, epsilon_start=0, epsilon_end=0, mutation_rate=0) 

env = ResourceAllocationEnvironment(NUM_AGENTS, total_resource_per_round=TOTAL_RESOURCE_PER_ROUND)

print(f"\n--- Starting {NUM_ROUNDS} Rounds of Cultural Evolution Framework - Emergent Division of Labor with Strong Nudge and Preferred Projects ---")

for i in range(NUM_ROUNDS):
    # Dynamic Environmental Changes (Same schedule as Eval 375 for consistency)
    if (i + 1) == 100: 
        env.add_project('Project_D', base_reward=12, resource_needed=6)
    if (i + 1) == 200: 
        env.update_project_params('Project_A', new_reward=18, new_resource_needed=8)
        env.add_project('Project_E', base_reward=20, resource_needed=10)
    if (i + 1) == 300: 
        if 'Project_C' in env.projects:
            env.remove_project('Project_C')
        env.update_project_params('Project_B', new_reward=25, new_resource_needed=9)
    if (i + 1) == 400: 
        env.update_project_params('Project_D', new_reward=10, new_resource_needed=4)
        env.add_project('Project_F', base_reward=15, resource_needed=7)

    individual_allocations_this_round_raw = {}

    for agent_id in all_agent_ids:
        individual_allocations_this_round_raw[agent_id] = agents_dict[agent_id].choose_allocation(
            TOTAL_RESOURCE_PER_ROUND // NUM_AGENTS, 
            env.projects, 
            i, NUM_ROUNDS
        )

    collective_allocations_for_round = defaultdict(int)
    for agent_id, agent_allocations in individual_allocations_this_round_raw.items():
        for project_id, amount in agent_allocations.items():
            collective_allocations_for_round[project_id] += amount

    project_rewards, total_collective_reward, completed_projects_this_round = env.distribute_and_resolve(collective_allocations_for_round)

    current_max_possible_collective_reward = sum(p.base_reward for p in env.projects.values())

    for agent_id in all_agent_ids:
        agent = agents_dict[agent_id]
        agent.record_allocations(individual_allocations_this_round_raw[agent_id]) 
        agent.calculate_specialization_index(len(env.projects)) 

        agent.update_learning( 
            my_allocations=individual_allocations_this_round_raw[agent_id],
            collective_round_reward=total_collective_reward,
            completed_projects_this_round=completed_projects_this_round,
            projects_map=env.projects, 
            max_possible_collective_reward_this_round=current_max_possible_collective_reward 
        )
        agents_dict[agent_id].update_reputation_from_round_outcome(total_collective_reward, max_possible_collective_reward_this_round=current_max_possible_collective_reward) 

    if (i + 1) % 100 == 0: 
        print(f"\n--- Cultural Transmission Check (Round {i+1}) ---")
        for agent_id in all_agent_ids:
            if agents_dict[agent_id].is_fixed_strategy: continue 

            dynamic_self_reward_threshold_for_adoption = (total_collective_reward / current_max_possible_collective_reward) * 0.75 if current_max_possible_collective_reward > 0 else 0 

            agents_dict[agent_id].consider_strategy_adoption(all_agents=agents_dict, current_round=i, total_rounds=NUM_ROUNDS,
                                                           adoption_threshold_self_reward_factor=dynamic_self_reward_threshold_for_adoption, 
                                                           adoption_threshold_other_rep=0.8, 
                                                           top_n_percent_mentors=0.25, max_possible_collective_reward_per_round=current_max_possible_collective_reward)

        print(f"\nRound {i+1} Summary (Current Projects: {[pid for pid in env.projects.keys()]}, Collective Reward: {total_collective_reward}, Epsilon_A1: {agents_dict['Agent_1']._get_epsilon(i, NUM_ROUNDS):.2f}, Epsilon_A3: {agents_dict['Agent_3']._get_epsilon(i, NUM_ROUNDS):.2f}):")
        for agent_id in all_agent_ids:
            agent = agents_dict[agent_id]
            print(f"  {agent.agent_id}: Total Reward = {agent.total_reward}")
            if not agent.is_fixed_strategy:
                for pid in env.projects.keys(): 
                    if pid in agent.allocation_strategy:
                        print(f"    {pid} Est: {agent.allocation_strategy[pid]['value_est']:.2f}")
                print(f"    Specialization: Most={agent.most_allocated_project}, Index={agent.specialization_index:.2f}")
                for rep_partner_id, rep_score in agent.reputations.items():
                    print(f"    Rep for {rep_partner_id}: {rep_score:.2f}")
            else:
                print(f"    Fixed strategy for {agent.fixed_project_id}")

print(f"\n--- Simulation Complete ---")
print("\nFinal Agent Rewards:")
for agent_id in all_agent_ids:
    agent = agents_dict[agent_id]
    print(f"  {agent.agent_id}: Total Reward = {agent.total_reward}")
    if not agent.is_fixed_strategy:
        for pid in env.projects.keys():
            if pid in agent.allocation_strategy:
                print(f"    {pid} Est: {agent.allocation_strategy[pid]['value_est']:.2f}")
        print(f"    Specialization: Most={agent.most_allocated_project}, Index={agent.specialization_index:.2f}")
        for rep_partner_id, rep_score in agent.reputations.items():
            print(f"    Rep for {rep_partner_id}: {rep_score:.2f}")
    else:
        print(f"    Fixed strategy for {agent.fixed_project_id}")

final_collective_reward_sum_of_totals = sum(agent.total_reward for agent in agents_dict.values())
print(f"Final Collective Reward (sum of individual totals): {final_collective_reward_sum_of_totals}")
